"""Command-line interface for the performance client and server."""
import os
import sys
import ipaddress
from dataclasses import dataclass

TRAILER = "For more information, try '--help'.\n"

@dataclass
class Option:
    name: str
    help: str
    kind: str = 'flag'
    default: str = None
    short: str = None
    extra: str = None
    metavar: str = None

    def value_name(self):
        return self.metavar or self.name.replace('-', '_').upper()

    def display(self):
        return '--' + self.name + ((' <' + self.value_name() + '>') if self.kind != 'flag' else '')

SIZE_REQUEST = 'This can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.'
SIZE_TRANSFER = 'This can use SI suffixes for sizes. For example, 1M will transfer 1MiB, 10G will transfer 10GiB.'
SIZE_LIMIT = 'This can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.'
COMMON = [
    Option('send-buffer-size', 'Send buffer size in bytes', 'size', '2M', extra=SIZE_REQUEST),
    Option('recv-buffer-size', 'Receive buffer size in bytes', 'size', '2M', extra=SIZE_REQUEST),
    Option('conn-stats', 'Whether to print connection statistics'),
    Option('keylog', 'Perform NSS-compatible TLS key logging to the file specified in `SSLKEYLOGFILE`'),
    Option('initial-mtu', 'UDP payload size that the network must be capable of carrying', 'u16', '1200'),
    Option('no-protection', 'Disable packet encryption/decryption (for debugging purpose)'),
    Option('initial-rtt', 'The initial round-trip-time (in msecs)', 'uint'),
    Option('ack-frequency', 'Ack Frequency mode'),
    Option('congestion', 'Congestion algorithm to use', 'congestion', metavar='CONG_ALG'),
    Option('stream-receive-window', 'Maximum number of bytes the peer may transmit without acknowledgement on any one stream before becoming blocked.', 'size', extra=SIZE_LIMIT),
    Option('receive-window', 'Maximum number of bytes the peer may transmit across all streams of a connection before becoming blocked.', 'size', extra=SIZE_LIMIT),
    Option('send-window', 'Maximum number of bytes to transmit to a peer without acknowledgment', 'size', extra=SIZE_LIMIT),
    Option('max-udp-payload-size', 'Max UDP payload size in bytes', 'u16', '1472'),
    Option('qlog', 'qlog output file', 'path', metavar='QLOG_FILE'),
]
SERVER = [
    Option('listen', 'Address to listen on', 'socket', '[::]:4433'),
    Option('key', 'TLS private key in DER format', 'path', short='k'),
    Option('cert', 'TLS certificate in PEM format', 'path', short='c'),
] + COMMON
CLIENT = [
    Option('ip', 'Override DNS resolution for host', 'ip'),
    Option('local-addr', 'Specify the local socket address', 'socket'),
    Option('uni-requests', 'Number of unidirectional requests to maintain concurrently', 'uint', '0'),
    Option('bi-requests', 'Number of bidirectional requests to maintain concurrently', 'uint', '1'),
    Option('download-size', 'Number of bytes to request', 'size', '1M', extra=SIZE_TRANSFER),
    Option('upload-size', 'Number of bytes to transmit, in addition to the request header', 'size', '1M', extra=SIZE_TRANSFER),
    Option('duration', 'The time to run in seconds', 'uint', '60'),
    Option('interval', 'The interval in seconds at which stats are reported', 'uint', '1'),
    Option('json', "File path to output JSON statistics to. If the file is '-', stdout will be used", 'path'),
] + COMMON
HELP = Option('help', 'Print help', short='h')
CONGESTIONS = ['cubic', 'bbr', 'new-reno']

class CLIExit(Exception):
    def __init__(self, text, code=2):
        self.text, self.code = text, code


def parse_integer(s, bits=64, signed=False):
    if not s:
        raise ValueError('cannot parse integer from empty string')
    negative = signed and s.startswith('-')
    data = s[1:] if s.startswith('+') or negative else s
    if not data:
        raise ValueError('invalid digit found in string')
    limit = (1 << (bits - 1)) - (0 if negative else 1) if signed else (1 << bits) - 1
    n = 0
    for c in data:
        if not '0' <= c <= '9':
            raise ValueError('invalid digit found in string')
        n = n * 10 + ord(c) - 48
        if n > limit:
            raise ValueError('number too small to fit in target type' if negative else 'number too large to fit in target type')
    return -n if negative else n


def parse_size(s):
    s = s.strip(' \t\r\n\v\f\x85\xa0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000')
    suffix = s[-1:] if s else ''
    shift = {'k': 10, 'M': 20, 'G': 30, 'T': 40}.get(suffix, 0)
    return (parse_integer(s[:-1] if shift else s) << shift) & ((1 << 64) - 1)


def parse_ip(s):
    try:
        if '%' in s:
            raise ValueError()
        return ipaddress.ip_address(s)
    except ValueError:
        raise ValueError('invalid IP address syntax') from None


def parse_socket(s):
    try:
        scope = 0
        if s.startswith('['):
            host, rest = s[1:].split(']', 1)
            if not rest.startswith(':'):
                raise ValueError()
            port = rest[1:]
            if '%' in host:
                host, sc = host.split('%', 1)
                if not sc.isascii() or not sc.isdecimal():
                    raise ValueError()
                scope = int(sc)
                if scope > 0xffffffff:
                    raise ValueError()
            ip = parse_ip(host)
            if ip.version != 6:
                raise ValueError()
        else:
            host, port = s.split(':')
            ip = parse_ip(host)
            if ip.version != 4:
                raise ValueError()
        if not port or not port.isascii() or not port.isdecimal() or len(port) > 5:
            raise ValueError()
        port = int(port)
        if port > 65535:
            raise ValueError()
        return (str(ip), port, 0, scope) if ip.version == 6 else (str(ip), port)
    except (ValueError, TypeError):
        raise ValueError('invalid socket address syntax') from None


def jaro(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    radius = max(0, max(len(a), len(b)) // 2 - 1)
    am = [False] * len(a)
    bm = [False] * len(b)
    matches = 0
    for i, ch in enumerate(a):
        for j in range(max(0, i-radius), min(len(b), i+radius+1)):
            if not bm[j] and ch == b[j]:
                am[i] = bm[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    aa = [x for x, m in zip(a, am) if m]
    bb = [x for x, m in zip(b, bm) if m]
    trans = sum(x != y for x, y in zip(aa, bb)) / 2
    return (matches / len(a) + matches / len(b) + (matches-trans)/matches) / 3


def suggest(value, choices):
    # Equal scores are ordered by spelling, matching deterministic CLI diagnostics.
    scores = sorted((jaro(value, c), c) for c in choices)
    return scores[-1][1] if scores and scores[-1][0] > .7 else None


class Parser:
    def __init__(self, prog):
        self.prog = os.path.basename(prog) or 'perf'
        self.command = None
        self.options = []
        self.seen = []
        self.values = {}

    def usage(self, selected=None, host=False):
        cmd = self.prog + ((' ' + self.command) if self.command else '')
        if self.command == 'help':
            return cmd + ' [COMMAND]...'
        if selected:
            for n in selected:
                if n == 'HOST':
                    continue
                opt = self.by_name.get(n, HELP)
                cmd += ' ' + opt.display()
            if self.command == 'client':
                cmd += ' <HOST>' if host else ' [HOST]'
            elif self.command is None:
                cmd += ' <COMMAND>'
            return cmd
        if self.command:
            return cmd + (' <HOST>' if host and self.command == 'client' else (' [OPTIONS] [HOST]' if self.command == 'client' else ' [OPTIONS]'))
        return cmd + ' <COMMAND>'

    def help_text(self, long=False):
        if self.command is None:
            return f"Usage: {self.usage()}\n\nCommands:\n  server  Run as a perf server\n  client  Run as a perf client\n  help    Print this message or the help of the given subcommand(s)\n\nOptions:\n  -h, --help  Print help\n"
        if self.command == 'help':
            return f'Print this message or the help of the given subcommand(s)\n\nUsage: {self.usage()}\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n'
        text = f'Run as a perf {self.command}\n\nUsage: {self.usage()}\n'
        if self.command == 'client':
            text += '\nArguments:\n'
            if long:
                text += '  [HOST]\n          Host to connect to\n          \n          [default: localhost:4433]\n'
            else:
                text += '  [HOST]  Host to connect to [default: localhost:4433]\n'
        text += '\nOptions:\n'
        for i, opt in enumerate(self.options + [HELP]):
            if long and i:
                text += '\n'
            text += (f'  -{opt.short}, ' if opt.short else '      ') + opt.display() + '\n'
            desc = opt.help
            if opt is HELP:
                desc += " (see a summary with '-h')" if long else " (see more with '--help')"
            elif not long:
                desc = desc.rstrip('.')
            text += '          ' + desc
            if long and opt.extra:
                text += '\n          \n          ' + opt.extra
            foot = None
            if opt.default is not None:
                foot = '[default: ' + opt.default + ']'
            if opt.kind == 'congestion':
                foot = '[possible values: cubic, bbr, new-reno]'
            if foot:
                text += ('\n          \n          ' if long else ' ') + foot
            text += '\n'
        return text

    def set_command(self, cmd):
        self.command = cmd
        self.options = CLIENT if cmd == 'client' else SERVER if cmd == 'server' else []
        self.by_name = {o.name: o for o in self.options + [HELP]}
        self.by_short = {o.short: o for o in self.options + [HELP] if o.short}

    def error(self, message, usage=None):
        text = 'error: ' + message + '\n\n'
        if usage is not None:
            text += 'Usage: ' + usage + '\n\n'
        if self.command != 'help':
            text += TRAILER
        raise CLIExit(text)

    def missing(self, opt):
        message = "a value is required for '" + opt.display() + "' but none was supplied"
        if opt.kind == 'congestion':
            message += '\n  [possible values: cubic, bbr, new-reno]'
        self.error(message)

    def unknown_subcommand(self, word, help_mode=False):
        message = "unrecognized subcommand '" + word + "'"
        if not help_mode and self.command is None:
            similar = suggest(word, ['server', 'client', 'help'])
            if similar:
                message += "\n\n  tip: a similar subcommand exists: '" + similar + "'"
        self.error(message, self.usage())

    def unknown(self, word, positional=False, after_dash=False):
        message = "unexpected argument '" + word + "' found"
        selected = list(self.seen) if not positional else []
        if after_dash and self.command is None and word in ['client','server','help']:
            message += f"\n\n  tip: subcommand '{word}' exists; to use it, remove the '--' before it"
        elif word.startswith('--') and not positional:
            similar = suggest(word[2:].split('=')[0], self.by_name)
            if similar:
                message += f"\n\n  tip: a similar argument exists: '--{similar}'"
                if similar not in selected:
                    selected.append(similar)
            elif self.command == 'client':
                message += f"\n\n  tip: to pass '{word}' as a value, use '-- {word}'"
        elif word.startswith('-') and not positional and self.command == 'client':
            message += f"\n\n  tip: to pass '{word}' as a value, use '-- {word}'"
        self.error(message, self.usage(selected, host=('HOST' in selected)))

    def add(self, opt, value):
        if opt.name in self.seen:
            self.error(f"the argument '{opt.display()}' cannot be used multiple times", self.usage())
        try:
            if opt.kind == 'uint':
                v = parse_integer(value)
            elif opt.kind == 'u16':
                v = parse_integer(value, signed=True)
                if not 0 <= v <= 65535:
                    raise ValueError(f'{v} is not in 0..=65535')
            elif opt.kind == 'size':
                v = parse_size(value)
            elif opt.kind == 'socket':
                v = parse_socket(value)
            elif opt.kind == 'ip':
                v = parse_ip(value)
            elif opt.kind == 'congestion':
                if value == '':
                    self.missing(opt)
                if value not in CONGESTIONS:
                    message = f"invalid value '{value}' for '{opt.display()}'\n  [possible values: cubic, bbr, new-reno]"
                    similar = suggest(value, CONGESTIONS)
                    if similar:
                        message += f"\n\n  tip: a similar value exists: '{similar}'"
                    self.error(message)
                v = value
            elif opt.kind == 'path':
                if not value:
                    self.missing(opt)
                v = value
            else:
                v = True
        except ValueError as e:
            self.error(f"invalid value '{value}' for '{opt.display()}': {e}")
        self.values[opt.name] = v
        self.seen.append(opt.name)

    def run(self, args):
        self.set_command(None)
        if not args or args == ['--']:
            raise CLIExit(self.help_text())
        if args[0] == 'help':
            for name in args[1:]:
                if self.command is None and name in ['server', 'client', 'help']:
                    self.set_command(name)
                else:
                    self.unknown_subcommand(name, help_mode=True)
            raise CLIExit(self.help_text(long=True), 0)
        i = 0
        stopped = False
        pending = None
        while i < len(args):
            word = args[i]
            i += 1
            if pending:
                opt, vals = pending
                if not (word.startswith('-') and word != '-') or stopped:
                    if not vals:
                        pending = opt, [word]
                        continue
                # Values are committed when the next option is reached, or at EOF.
                if word.startswith('-') and word != '-':
                    if vals:
                        self.add(opt, vals[0])
                        pending = None
                    elif word == '--' or word.split('=')[0][2:] in self.by_name or (word.startswith('-') and not word.startswith('--') and word[1:2] in self.by_short):
                        self.missing(opt)
                    else:
                        bad = word.split('=')[0] if word.startswith('--') else word[:2]
                        self.unknown(bad)
            if word == '--' and not stopped:
                stopped = True
                continue
            if not stopped and word.startswith('-') and word != '-':
                if word.startswith('--'):
                    name, eq, value = word[2:].partition('=')
                    opt = self.by_name.get(name)
                    if opt is None:
                        self.unknown('--' + name)
                    if opt.kind == 'flag':
                        if eq:
                            self.error(f"unexpected value '{value}' for '--{name}' found; no more were expected", self.usage([name]))
                        if opt is HELP:
                            raise CLIExit(self.help_text(True), 0)
                        self.add(opt, True)
                    else:
                        pending = (opt, [value] if eq else [])
                else:
                    j = 1
                    while j < len(word):
                        ch = word[j]
                        opt = self.by_short.get(ch)
                        if opt is None:
                            self.unknown('-' + ch)
                        if opt is HELP:
                            raise CLIExit(self.help_text(False), 0)
                        if opt.kind == 'flag':
                            self.add(opt, True)
                            j += 1
                        else:
                            rest = word[j+1:]
                            if rest.startswith('='):
                                rest = rest[1:]
                                pending = (opt, [rest])
                            else:
                                pending = (opt, [rest] if rest else [])
                            break
            elif self.command is None and not stopped:
                if word not in ['client', 'server']:
                    self.unknown_subcommand(word)
                self.set_command(word)
            elif self.command == 'client' and 'HOST' not in self.seen:
                self.values['host'] = word
                self.seen.append('HOST')
            else:
                self.unknown(word, positional=True, after_dash=stopped)
        if pending:
            opt, vals = pending
            if not vals:
                self.missing(opt)
            self.add(opt, vals[0])
        if self.command is None:
            raise CLIExit(self.help_text())
        if self.command == 'server' and (('key' in self.seen) != ('cert' in self.seen)):
            missing = 'cert' if 'key' in self.seen else 'key'
            supplied = 'key' if missing == 'cert' else 'cert'
            selected = [supplied, missing] + [s for s in self.seen if s != supplied]
            self.error("the following required arguments were not provided:\n  " + self.by_name[missing].display(), self.usage(selected))
        for opt in self.options:
            if opt.name not in self.values:
                if opt.default is not None:
                    self.add(opt, opt.default)
                elif opt.kind == 'flag':
                    self.values[opt.name] = False
                else:
                    self.values[opt.name] = None
        if self.command == 'client':
            self.values.setdefault('host', 'localhost:4433')
        return self.command, self.values


def colorize_cli(text):
    # CLI color is automatic for terminals, unlike the timestamped runtime logs.
    enabled = ('NO_COLOR' not in os.environ and os.environ.get('CLICOLOR') != '0' and
               (sys.stderr.isatty() or os.environ.get('CLICOLOR_FORCE', '0') != '0'))
    if not enabled:
        return text
    import re
    text = re.sub(r'^error:', '\x1b[1m\x1b[31merror:\x1b[0m', text)
    text = re.sub(r'(?m)^(Usage:|Commands:|Options:|Arguments:)', r'\x1b[1m\1\x1b[0m', text)
    return text
