import sys
import time
from cli import parse_integer, parse_ip, parse_socket


class Failure(Exception):
    pass


def os_error(e):
    return f'{os.strerror(e.errno)} (os error {e.errno})'


class Log:
    levels = {'off':0, 'error':1, 'warn':2, 'info':3, 'debug':4, 'trace':5}
    colors = {'error':31,'warn':33,'info':32,'debug':34,'trace':35}

    def __init__(self):
        self.color = not os.environ.get('NO_COLOR')
        self.filters = []
        raw = os.environ.get('RUST_LOG', 'warn')
        try:
            for part in raw.split(','):
                if not part:
                    continue
                if part.lower() in self.levels:
                    self.filters.append(('', self.levels[part.lower()]))
                elif part in ['0','1','2','3','4','5']:
                    self.filters.append(('',int(part)))
                elif '=' in part:
                    name, level = part.rsplit('=',1)
                    self.filters.append((name, self.levels[level.lower()]))
                else:
                    self.filters.append((part, 5))
        except (KeyError,ValueError):
            self.filters = [('',2)]

    def enabled(self, level, target):
        threshold, length = 0, -1
        for name, val in self.filters:
            if target.startswith(name) and len(name) >= length:
                threshold, length = val, len(name)
        return self.levels[level] <= threshold

    def __call__(self, level, target, text):
        if not self.enabled(level,target):
            return
        timestamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.%fZ')
        label = level.upper().rjust(5)
        if self.color:
            text = f'\x1b[2m{timestamp}\x1b[0m \x1b[{self.colors[level]}m{label}\x1b[0m \x1b[2m{target}\x1b[0m\x1b[2m:\x1b[0m {text}'
        else:
            text = f'{timestamp} {label} {target}: {text}'
        print(text, flush=True)


