def address_text(addr):
    ip, port = addr[:2]
    if ':' not in ip:
        return f'{ip}:{port}'
    if '%' in ip:
        ip = ip.split('%')[0]
    ip = str(ipaddress.ip_address(ip))
    if ip.startswith('::ffff:'):
        mapped = ipaddress.IPv6Address(ip).ipv4_mapped
        if mapped:
            ip = '::ffff:' + str(mapped)
    scope = addr[3] if len(addr) > 3 else 0
    return f'[{ip}{"%"+str(scope) if scope else ""}]:{port}'


