"""A UDP QUIC endpoint with stream reassembly and TLS 1.3 negotiation."""
from collections import deque
import os
import socket
import time
from crypto import initial_keys
from tls import TLS, parameters
from wire import (Reader, varint, peek_header, decode_packet, encode_packet, frames,
