class Reassembly:
    def __init__(self):
        self.offset=0
        self.pending={}
        self.final_size=None
        self.complete=False

    def feed(self, offset, data, fin=False):
        if fin:
            self.final_size=offset+len(data)
        if offset<self.offset:
            data=data[self.offset-offset:]
            offset=self.offset
        if data:
            old=self.pending.get(offset)
            if old is None or len(old)<len(data):
                self.pending[offset]=data
        output=[]
        while self.pending:
            low=min(self.pending)
            if low>self.offset:
                break
            part=self.pending.pop(low)
            if low<self.offset:
                part=part[self.offset-low:]
            self.offset+=len(part)
            output.append(part)
        finished=self.final_size==self.offset and not self.complete
