    def open_stream(self,uni=False):
        sid=self.next_uni if uni else self.next_bi
        if uni:self.next_uni+=4
        else:self.next_bi+=4
        return sid

    def send_stream(self,sid,prefix=b'',size=0,fin=True,offset=0):
        self.outgoing.append(Outgoing(sid,prefix,size,fin,offset))

    def poll(self):
        if self.closed or self.closing:
            return
