        while self.outgoing and budget>0 and count<100:
            o=self.outgoing[0]
            if (o.sid & 1)==(0 if self.client else 1):
                stream_limit=self.peer_limits.get(9 if o.sid&2 else 8,0)
                if o.sid//4>=stream_limit:
                    break
