    def statistics(self):
        def debug_fields(x):
            return ', '.join(k+': '+str(v) for k,v in x.items())
        rtt=(str(round(self.rtt*1000000,3))+'µs') if self.rtt<.001 else (str(round(self.rtt*1000,6))+'ms')
