import os
import signal
import sys
from cli import Parser, CLIExit, colorize_cli


def main():
    signal.signal(signal.SIGINT,signal.SIG_DFL)
    signal.signal(signal.SIGPIPE,signal.SIG_DFL)
    try:
        mode,options=Parser(sys.argv[0]).run(sys.argv[1:])
    except CLIExit as e:
        output=sys.stdout if e.code==0 else sys.stderr
        output.write(colorize_cli(e.text))
        return e.code
    from runtime import Failure, log
    from perf import run_client, run_server
    try:
        (run_server if mode=='server' else run_client)(options)
    except Failure as e:
        log('error','quinn_perf',str(e))
    return 0


if __name__=='__main__':
    sys.exit(main())
