"""Interval reports and cumulative stream histograms."""
import json
import math
import time
from collections import Counter


class Histogram:
    def __init__(self):
        self.counts=Counter()
        self.count=0
        self.total=0

    def record(self,value):
        value=max(0,min((1<<64)-1,int(value)))
        step=1 << max(0,value.bit_length()-11)
        low=(value//step)*step
        self.counts[(low,step)]+=1
        self.count+=1
        self.total+=low+(step//2)

    def mean(self):
        return self.total/self.count if self.count else 0

    def quantile(self,q):
        if not self.count:
            return 0
        required=max(1,math.ceil(self.count*q))
        collected=0
        for (low,step),count in sorted(self.counts.items()):
            collected+=count
            if collected>=required:
                return low if q==0 else min((1<<64)-1,low+step-1)
        return 0


def duration_string(seconds):
    seconds=max(0,seconds)
    if seconds>=1:
        return f'{seconds:.2f}s'
    if seconds>=.001:
        return f'{seconds*1000:.2f}ms'
    if seconds>=.000001:
        return f'{seconds*1000000:.2f}µs'
    return f'{seconds*1000000000:.2f}ns'


class Metrics:
    def __init__(self, opts):
        self.opts=opts
        self.start=time.monotonic()
        self.timestamp=int(time.time())
        self.last=0.00003
        self.events=[]
        self.intervals=[]
        self.upload=Histogram()
        self.download=Histogram()
        self.fbl=Histogram()
        self.upload_rate=Histogram()
        self.download_rate=Histogram()

    def record(self,sid,sender,size,duration,first_byte=None):
        if not size:
            return
        micros=int(max(0,duration)*1000000)
        rate=min((1<<64)-1,int(size*1000000/micros)) if micros else (1<<64)-1
        if sender:
            self.upload.record(micros)
            self.upload_rate.record(rate)
        else:
            self.download.record(micros)
            self.download_rate.record(rate)
            self.fbl.record(int(max(0,first_byte or 0)*1000000))
        self.events.append((sid,size,sender))

    def report(self,connection):
        now=time.monotonic()
        elapsed=now-self.start
        n=self.download.count
        lines=['Overall stats:',f'RPS: {n/elapsed if elapsed else 0:.2f} ({n} requests in {duration_string(elapsed)})','',
            'Stream metrics:','',
            '      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput',
            '──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────']
        columns=[self.upload,self.download,self.fbl,self.upload_rate,self.download_rate]
        for label,q in [('AVG',None),('P0',0),('P10',.1),('P50',.5),('P90',.9),('P100',1)]:
            vals=[c.mean() if q is None else c.quantile(q) for c in columns]
            times=[duration_string(int(x)/1000000) for x in vals[:3]]
            rates=[f'{x*8/1000000:.2f} Mb/s' for x in vals[3:]]
            lines.append(f' {label:<4} │ {times[0]:>15} │ {times[1]:>17} │ {times[2]:>10} │ {rates[0]:>17} │ {rates[1]:>18}')
        print('\n'.join(lines)+'\n',flush=True)
        if self.opts.get('conn-stats'):
            print(connection.statistics()+'\n',flush=True)
        if self.opts.get('json') is not None:
            start=self.last
            length=elapsed-start
            records=[]
            sender=bool(self.opts.get('upload-size'))
            total=0
            for sid,size,direction in self.events:
                record={'id':sid,'start':start,'end':elapsed,'seconds':length,'bytes':size,'bits_per_second':size*8/length if length else 0.0,'sender':direction}
                records.append(record)
                if direction==sender:
                    total+=size
            summary={'start':start,'end':elapsed,'seconds':length,'bytes':total,'bits_per_second':total*8/length if length else 0.0,'sender':sender}
            self.intervals.append({'streams':records,'sum':summary})
        self.events=[]
        self.last=time.monotonic()-self.start

    def json(self):
        return json.dumps({'start':{'timestamp':{'timesecs':self.timestamp}},'intervals':self.intervals},separators=(',',':'),ensure_ascii=False)
