        self.requests[sid]={'start':now,'uploaded':False,'sent':False,'uni':uni,'download_start':None,'first':None,'end':None,'count':0,'done':False}
        self.con.send_stream(sid,self.opts['download-size'].to_bytes(8,'big'),self.opts['upload-size'])
        if uni:
            self.uni_uploads.append(sid)

    def start(self):
        self.started=True
        # Lazily schedule very large concurrency counts instead of reserving huge buffers.
        for _ in range(min(10000,self.opts['uni-requests'])):
            self.start_one(True)
        for _ in range(min(10000,self.opts['bi-requests'])):
            self.start_one(False)

    def sent(self,con,sid):
        if sid in self.requests:
            self.requests[sid]['sent']=True
            # With no body, the request is not measured as an upload.
            if not self.opts['upload-size']:
                self.requests[sid]['download_start']=time.monotonic()
                if not self.opts['download-size'] and not self.requests[sid]['uni']:
                    con.control.append(b'\x05'+varint(sid)+b'\0')

    def acked(self,con,sid):
        req=self.requests.get(sid)
        if req is None or req['uploaded']:
            return
        now=time.monotonic()
        req['uploaded']=True
        self.metrics.record(sid,True,self.opts['upload-size'],now-req['start'])
        if req['download_start'] is None:
            req['download_start']=now
        if req['uni']:
            self.pending_start.append(True)
        elif not self.opts['download-size']:
            con.control.append(b'\x05'+varint(sid)+b'\0')
            self.finish(sid)
        elif req['end'] is not None:
            self.finish(sid)

    def stream(self,con,sid,data,fin):
        now=time.monotonic()
        if sid&2:
            response=self.responses.setdefault(sid,{'start':now,'first':now,'count':0})
            response['count']+=len(data)
            if fin or response['count']>=self.opts['download-size']:
                self.metrics.record(sid,False,self.opts['download-size'],now-response['start'],response['first']-response['start'])
                self.responses.pop(sid,None)
            return
        req=self.requests.get(sid)
        if req is None or req['done']:
            return
        req['count']+=len(data)
        if req['first'] is None:
            req['first']=now
        if fin or req['count']>=self.opts['download-size']:
            req['end']=now
            if req['uploaded']:
                self.finish(sid)

    def finish(self,sid):
        req=self.requests.get(sid)
        if req is None or req['done']:
            return
        req['done']=True
        if self.opts['download-size']:
            start=req['download_start'] or req['start']
            end=req['end'] or time.monotonic()
            first=max(start,req['first'] or end)
            self.metrics.record(sid,False,self.opts['download-size'],max(0,end-start),max(0,first-start))
        self.pending_start.append(False)
        del self.requests[sid]

    def reset(self,con,sid,error):
        req=self.requests.get(sid)
        if req and req['uploaded'] and not req['uni'] and not self.opts['download-size']:
            self.finish(sid)

    def poll(self):
        start,self.pending_start=self.pending_start,[]
        for uni in start:
            self.start_one(uni)


def run_client(opts):
    host,remote,local=resolve(opts)
    sock=bind_socket(local,opts)
    validate_transport(opts)
    qlog=Qlog(opts.get('qlog'),True)
    remote_ip=ipaddress.ip_address(remote[0].split('%')[0])
    invalid=remote[1]==0 or remote_ip.is_unspecified or (sock.family==socket.AF_INET and remote_ip.version==6)
    if invalid:
        raise Failure('invalid remote address: '+address_text(remote))
    if not valid_server_name(host):
        raise Failure('invalid server name: '+host)
    sock.setblocking(False)
    con=Connection(sock,remote,opts,True,host=host,qlog=qlog)
    con.on_connect=lambda c:log('info','perf::client','established')
    con.start()
    while not con.connected:
        ready,_,_=select.select([sock],[],[],.01)
        if ready:
            try:
                data,peer=sock.recvfrom(65535)
            except OSError:
                data=b''
            if data:
                con.receive(data)
        if con.closed:
            raise Failure('connecting: '+con.closed)
        if time.monotonic()-con.start_time>=30:
            raise Failure('connecting: timed out')
        con.poll()
    if opts['duration']>0x7fffffffffffffff or opts['interval']>0x7fffffffffffffff:
        panic('overflow when adding duration to instant','/rustc/unknown/library/std/src/time.rs:429:33')
    metrics=Metrics(opts)
    requests=ClientRequests(con,opts,metrics)
    duration=opts['duration']
    interval=opts['interval']
    active=bool(opts['bi-requests'] or opts['uni-requests'])
    end=metrics.start+duration+.2 if active else float('inf')
    # The measurement and request workers begin together; the final 200 ms lets
    # in-flight requests drain while reports retain their configured boundaries.
    next_report=metrics.start+interval
    if duration>0:
        requests.start()
    while time.monotonic()<end:
        now=time.monotonic()
        if active and now>=next_report and now<=metrics.start+duration+.01:
            metrics.report(con)
            next_report+=interval if interval else .001
        ready,_,_=select.select([sock],[],[],.001 if con.outgoing else .005)
        if ready:
            for _ in range(256):
                try:
                    data,peer=sock.recvfrom(65535)
                except BlockingIOError:
                    break
                except OSError:
                    break
                if data:
                    con.receive(data)
        requests.poll()
        con.poll()
        if con.closed:
            break
        if time.monotonic()-con.last_recv>30:
            con.closed='timed out'
            break
    requests.stopped=True
    log('info','perf::client','shutting down')
    con.close()
    # Errors are emitted by request workers stopped while operating a stream.
    for _ in range(min(10000,opts['uni-requests'])):
        reason='connection lost: closed' if duration==0 and opts['upload-size'] else 'closed'
        log('error','perf::client','sending request failed: '+reason)
    if opts['download-size'] or duration==0:
        for _ in range(min(10000,opts['bi-requests'])):
            log('error','perf::client','request failed: connection lost: closed')
    # Keep the endpoint alive for a closing retransmission interval.
    until=time.monotonic()+.08
    while time.monotonic()<until:
        ready,_,_=select.select([sock],[],[],.005)
        if ready:
            try:
                data,peer=sock.recvfrom(65535)
                if data:
                    con.receive(data)
            except OSError:
                pass
    if opts.get('json') is not None:
        text=metrics.json()
        if opts['json']=='-':
            print(text,end='',flush=True)
        else:
            try:
                with open(opts['json'],'w') as f:
                    f.write(text)
            except OSError as e:
                raise Failure(os_error(e)) from None
    qlog.close()
